import sys

k = int(sys.stdin.read().split()[0])
count = 0
stack = [("", 0)]
while stack:
    s, cs = stack.pop()
    if len(s) == k:
        count += 1
        continue
    for ch in "abc":
        if ch == "a" and s.endswith("a"):
            continue
        if ch == "c" and cs == 1:
            continue
        stack.append((s + ch, cs + (ch == "c")))
print(count % (10**9 + 7))

